adcs_status_t status = ADCS_OK;
adcs_vec3_t rate_val = {0, 0, 0};
adcs_actuator_command_t cmd_val = {{0, 0, 0}, 0U};
adcs_vec3_t torque_val = {0, 0, 0};

// Check for NULL pointers
if ((previous == NULL) || (current == NULL) || (rate == NULL) || (command == NULL) || (torque == NULL)) {
    return ADCS_E_NULL;
}

// Check for finite fields and times, and strictly increasing time
int prev_finite = adcs_is_finite_vec3(previous);
int curr_finite = adcs_is_finite_vec3(current);
if ((!prev_finite) || (!curr_finite) || (!isfinite(previous_time)) || (!isfinite(current_time)) || (current_time <= previous_time)) {
    *rate = (adcs_vec3_t){0, 0, 0};
    *command = (adcs_actuator_command_t){{0, 0, 0}, 0U};
    *torque = (adcs_vec3_t){0, 0, 0};
    return ADCS_E_RANGE;
}

// Prepare temporary state for adcs_bdot_update to represent the history
adcs_bdot_state_t hist_state;
hist_state.previous_field_t = *previous;
hist_state.previous_time_s = previous_time;
hist_state.initialized = 1;

// Compute projected B-dot rate with alpha = 1 (unfiltered difference)
status = adcs_bdot_update(&hist_state, current, current_time, 1.0, &rate_val);
if (status != ADCS_OK) {
    *rate = (adcs_vec3_t){0, 0, 0};
    *command = (adcs_actuator_command_t){{0, 0, 0}, 0U};
    *torque = (adcs_vec3_t){0, 0, 0};
    return status;
}

// Compute dipole command
status = adcs_bdot_dipole(current, &rate_val, gain, limit, &cmd_val);
if (status == ADCS_E_DEGENERATE) {
    // Field is degenerate, command is already zeroed by adcs_bdot_dipole
    *rate = rate_val;
    *command = cmd_val;
    *torque = (adcs_vec3_t){0, 0, 0};
    return ADCS_E_DEGENERATE;
} else if (status != ADCS_OK) {
    // Other errors propagate
    *rate = (adcs_vec3_t){0, 0, 0};
    *command = (adcs_actuator_command_t){{0, 0, 0}, 0U};
    *torque = (adcs_vec3_t){0, 0, 0};
    return status;
}

// Calculate torque generated by the dipole command in the current field: T = m x B
torque_val = adcs_vec3_cross(&cmd_val.command, current);

// Assign final outputs
*rate = rate_val;
*command = cmd_val;
*torque = torque_val;

return ADCS_OK;

