adcs_status_t status;
double dt;
adcs_vec3_t delta;
adcs_vec3_t zero_vec = {0.0, 0.0, 0.0};

// 1. Null checks
if ((previous == NULL) || (current == NULL) || (rate == NULL) || 
    (command == NULL) || (torque == NULL)) {
    return ADCS_E_NULL;
}

// 2. Finite checks for inputs
if ((!adcs_is_finite_vec3(previous)) || (!adcs_is_finite_vec3(current)) ||
    (!isfinite(previous_time)) || (!isfinite(current_time)) ||
    (!isfinite(gain)) || (!isfinite(limit))) {
    *rate = zero_vec;
    command->command = zero_vec;
    command->saturated_axes = 0U;
    *torque = zero_vec;
    return ADCS_E_RANGE;
}

// 3. Time check: strictly increasing
dt = current_time - previous_time;
if (dt <= 0.0) {
    *rate = zero_vec;
    command->command = zero_vec;
    command->saturated_axes = 0U;
    *torque = zero_vec;
    return ADCS_E_RANGE;
}

// 4. Gain/Limit negative check
if (gain < 0.0 || limit < 0.0) {
    *rate = zero_vec;
    command->command = zero_vec;
    command->saturated_axes = 0U;
    *torque = zero_vec;
    return ADCS_E_RANGE;
}

// 5. Compute B-dot rate manually equivalent to adcs_bdot_update with alpha=1
delta = adcs_vec3_sub(current, previous);
*rate = adcs_vec3_scale(&delta, 1.0 / dt);

// 6. Compute dipole command using adcs_bdot_dipole
status = adcs_bdot_dipole(current, rate, gain, limit, command);

// 7. Handle errors from dipole calculation
if (status != ADCS_OK) {
    // Failure outputs zero for all fields
    *rate = zero_vec;
    command->command = zero_vec;
    command->saturated_axes = 0U;
    *torque = zero_vec;
    return status;
}

// 8. Verify torque = m cross B
*torque = adcs_vec3_cross(&command->command, current);

return ADCS_OK;

